<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { UserRound, LockKeyhole, Save, LoaderCircle } from '@lucide/vue';
import { getCurrentUser, updateNickname } from '../api';
import { trainingStore } from '../stores/training';
const nickname=ref(''),realName=ref(''),email=ref(''),loading=ref(true),saving=ref(false),error=ref(''),message=ref('');
onMounted(async()=>{try{const user=await getCurrentUser();nickname.value=user.nickname||user.name;realName.value=user.name;email.value=user.email||'';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}});
async function save(){error.value='';message.value='';if(!nickname.value.trim()){error.value='请填写昵称。';return;}saving.value=true;try{const user=await updateNickname(nickname.value.trim());nickname.value=user.nickname||user.name;trainingStore.saveProfile({name:user.name,nickname:nickname.value});message.value='昵称已保存';}catch(e){error.value=(e as Error).message;}finally{saving.value=false;}}
</script>
<template>
 <div class="account-settings"><header><span><UserRound :size="30"/></span><div><h1>账户设置</h1><p>设置你的昵称，真实姓名用于教学身份识别。</p></div></header>
 <form @submit.prevent="save"><p v-if="loading" role="status">正在加载账户信息…</p><template v-else><label>真实姓名<div class="readonly-field"><LockKeyhole :size="18"/><input :value="realName" readonly aria-label="真实姓名"/></div><small>注册时填写，不能自行修改。教师仍会看到这个姓名。</small></label><label>邮箱<input :value="email||'未绑定邮箱'" readonly aria-label="邮箱"/><small>新注册账号使用邮箱登录，昵称修改不影响登录。</small></label><label>昵称<input v-model="nickname" required maxlength="40" autocomplete="nickname" aria-label="昵称" placeholder="填写你喜欢的昵称" :disabled="saving"/><small>支持中文、字母、数字、表情和符号，最多40个字符。</small></label><p v-if="message" class="success" role="status">{{message}}</p><button class="primary" type="submit" :disabled="saving||!realName"><LoaderCircle v-if="saving" :size="18"/><Save v-else :size="18"/>{{saving?'正在保存…':'保存昵称'}}</button></template><p v-if="error" class="error" role="alert">{{error}}</p></form></div>
</template>
<style scoped>
.account-settings{max-width:850px;margin:24px auto;padding:0 22px;color:#102a56}.account-settings header{display:flex;align-items:center;gap:18px;padding:24px 30px;background:linear-gradient(110deg,#e7f2ff,#c9e2ff);border-radius:20px}.account-settings header>span{width:60px;height:60px;border-radius:18px;background:#fff8;color:#155eef;display:grid;place-items:center}.account-settings h1{font-size:28px;margin:0 0 6px}.account-settings header p{margin:0;font-size:14px;color:#526b90}.account-settings form{display:grid;gap:23px;padding:32px;margin-top:18px;background:white;border:1px solid #e3edff;border-radius:20px;box-shadow:0 8px 25px #155eef0a}.account-settings label{display:grid;gap:9px;font-size:15px;font-weight:700}.account-settings input{width:100%;box-sizing:border-box;min-width:0;padding:12px 15px;border:1px solid #cbdcff;border-radius:10px;background:#fbfdff;color:#102a56;font:inherit;outline-color:#155eef}.account-settings input[readonly]{background:#f2f6fb;color:#60758f;cursor:default}.account-settings small{font-size:12px;color:#64748b;font-weight:400;line-height:1.7}.readonly-field{display:flex;align-items:center;background:#f2f6fb;border:1px solid #cbdcff;border-radius:10px;padding-left:14px;color:#8196b1}.readonly-field input{border:0}.account-settings .primary{display:flex;align-items:center;justify-content:center;gap:9px;justify-self:start;padding:12px 24px;border:0;border-radius:11px;background:linear-gradient(110deg,#168aff,#155eef);color:white;font-size:14px;cursor:pointer}.primary:disabled{opacity:.55}.error,.success{padding:12px;border-radius:9px;font-size:13px;margin:0}.error{background:#fff0ed;color:#b42318}.success{background:#e7f8ef;color:#137944}@media(max-width:600px){.account-settings{padding:0 12px;margin:14px auto}.account-settings header{padding:22px 18px}.account-settings form{padding:24px 20px}.account-settings h1{font-size:24px}.account-settings header p{font-size:12px}}
</style>
